package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.List;
/** Pure fail-closed production-equivalent completion-probability composition without economics or selection. */
final class BuyReplacementRoundTripCompletionEvaluator {
 BuyReplacementRoundTripCompletionEvaluationSet evaluate(BuyReplacementSellFillViabilityAssessment s,long at){if(s==null||s.getOutcome()!=BuyReplacementSellFillViabilityOutcome.VIABLE||at<s.getAssessedAt()||s.getAssessedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty()||s.getViableCandidates()==null||s.getViableCandidates().isEmpty())return null;List<BuyReplacementRoundTripCompletionEvaluation> out=new ArrayList<>(s.getViableCandidates().size());int completeIndex=0;for(BuyReplacementSellFillViableCandidate v:s.getViableCandidates()){while(completeIndex<s.getEvaluations().size()&&!matches(v,s.getEvaluations().get(completeIndex)))completeIndex++;if(completeIndex>=s.getEvaluations().size()||!valid(v,s))return null;double p=v.getBuyProbability()*v.getSellProbability();if(!Double.isFinite(p)||p<=0||p>1)return null;out.add(new BuyReplacementRoundTripCompletionEvaluation(v,p));completeIndex++;}return new BuyReplacementRoundTripCompletionEvaluationSet(s,out,at);}
 private static boolean valid(BuyReplacementSellFillViableCandidate v,BuyReplacementSellFillViabilityAssessment s){return v!=null&&v.getExactRemainderQuantity()==s.getExactRemainderQuantity()&&Double.isFinite(v.getBuyProbability())&&v.getBuyProbability()>0&&v.getBuyProbability()<=1&&Double.isFinite(v.getSellProbability())&&v.getSellProbability()>0&&v.getSellProbability()<=1&&Double.isFinite(v.getBuyExpectedHours())&&v.getBuyExpectedHours()>=0&&Double.isFinite(v.getSellExpectedHours())&&v.getSellExpectedHours()>=0;}
 private static boolean matches(BuyReplacementSellFillViableCandidate v,BuyReplacementSellFillEvaluation e){return v!=null&&e!=null&&v.getBuyOffsetIndex()==e.getBuyOffsetIndex()&&Double.compare(v.getBuyOffset(),e.getBuyOffset())==0&&v.getBuyPrice()==e.getBuyPrice()&&v.getExactRemainderQuantity()==e.getExactRemainderQuantity()&&v.getTotalCost()==e.getTotalCost()&&Double.compare(v.getBuyProbability(),e.getBuyProbability())==0&&Double.compare(v.getBuyExpectedHours(),e.getBuyExpectedHours())==0&&Double.compare(v.getBuyUnitsPerHour(),e.getBuyUnitsPerHour())==0&&Double.compare(v.getBuyWaitHours(),e.getBuyWaitHours())==0&&v.getSellOffsetIndex()==e.getSellOffsetIndex()&&Double.compare(v.getSellOffset(),e.getSellOffset())==0&&v.getSellPrice()==e.getSellPrice()&&v.getRawSpreadPerItem()==e.getRawSpreadPerItem()&&v.getTaxPerItem()==e.getTaxPerItem()&&v.getNetMarginPerItem()==e.getNetMarginPerItem()&&v.getTotalTax()==e.getTotalTax()&&v.getTotalNetMargin()==e.getTotalNetMargin()&&Double.compare(v.getSellProbability(),e.getSellProbability())==0&&Double.compare(v.getSellExpectedHours(),e.getSellExpectedHours())==0&&Double.compare(v.getSellUnitsPerHour(),e.getSellUnitsPerHour())==0&&Double.compare(v.getSellWaitHours(),e.getSellWaitHours())==0;}
}
